import 'package:flutter/material.dart';
import 'package:mobile_scanner/mobile_scanner.dart';
import 'package:geolocator/geolocator.dart';
import '../services/api_service.dart';

class ScanScreen extends StatefulWidget { const ScanScreen({super.key}); @override State<ScanScreen> createState()=>_ScanScreenState(); }
class _ScanScreenState extends State<ScanScreen>{final controller=MobileScannerController();bool busy=false;String message='Arahkan kamera ke QR absensi';Color messageColor=const Color(0xFF9CB3C4);bool done=false;
Future<void>scan(String raw)async{if(busy||done)return;setState(()=>busy=true);try{if(!raw.trim().isNotEmpty)throw Exception('Token QR kosong.');final service=await Geolocator.isLocationServiceEnabled();if(!service)throw Exception('Aktifkan GPS terlebih dahulu.');var permission=await Geolocator.checkPermission();if(permission==LocationPermission.denied)permission=await Geolocator.requestPermission();if(permission==LocationPermission.denied||permission==LocationPermission.deniedForever)throw Exception('Izin lokasi diperlukan untuk absensi.');final pos=await Geolocator.getCurrentPosition(locationSettings:const LocationSettings(accuracy:LocationAccuracy.high));final r=await ApiService.scan(raw.trim(),pos.latitude,pos.longitude);setState(()=>message='✓ ${r['message']??'Absensi berhasil'}');messageColor=const Color(0xFF6BD5A3);done=true;await controller.stop();}catch(e){setState(()=>message=e.toString().replaceFirst('Exception: ',''));messageColor=const Color(0xFFE3A1AE);await Future.delayed(const Duration(milliseconds:1200));}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Scan QR',style:TextStyle(fontWeight:FontWeight.w800)),actions:[IconButton(onPressed:()=>controller.toggleTorch(),icon:const Icon(Icons.flash_on))]),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Expanded(child:ClipRRect(borderRadius:BorderRadius.circular(22),child:Stack(fit:StackFit.expand,children:[MobileScanner(controller:controller,onDetect:(capture){for(final b in capture.barcodes){final v=b.rawValue;if(v!=null){scan(v);break;}}}),Center(child:Container(width:240,height:240,decoration:BoxDecoration(border:Border.all(color:const Color(0xFF72D1FF),width:2),borderRadius:BorderRadius.circular(22))))]))),const SizedBox(height:16),Container(width:double.infinity,padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:const Color(0xFF0B1D31),borderRadius:BorderRadius.circular(17),border:Border.all(color:const Color(0xFF1B3D59))),child:Row(children:[Icon(done?Icons.check_circle:Icons.gps_fixed,color:messageColor),const SizedBox(width:10),Expanded(child:Text(message,style:TextStyle(color:messageColor,fontWeight:FontWeight.w700)))])),const SizedBox(height:12),if(busy)const LinearProgressIndicator(minHeight:2),if(done)Padding(padding:const EdgeInsets.only(top:14),child:OutlinedButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Kembali ke Dashboard'))),const SizedBox(height:10)]));}
}
